{"cmd":"python - <<'PY'
import os, signal
pids = []
for pid in os.listdir('/proc'):
    if not pid.isdigit():
        continue
    try:
        with open(f'/proc/{pid}/cmdline','rb') as f:
            cmd = f.read().decode(errors='ignore')
    except Exception:
        continue
    if 'run_association.py' in cmd:
        pids.append(int(pid))

for pid in pids:
    try:
        os.kill(pid, signal.SIGKILL)
    except Exception:
        pass
print('killed', len(pids))
